#!/usr/bin/env node
// Generates the per-language offline glossary addons from the master data.
//
//   node tools/build-glossary.js           write addon/WoWChatHelper_Glossary_<locale>/
//   node tools/build-glossary.js --check   exit 1 if any generated file is missing or stale
//
// Input (single source of truth):
//   data/glossary/terms.json    [{ term, aliases, expansion, cat, ambiguity, examples,
//                                  tr: { <locale>: "..." } }]
//   data/glossary/phrases.json  [{ key, terms: ["<term>", ...], tr: { <locale>: "..." } }]
//                               phrase terms name entries of terms.json (case-insensitive)
//
// Output, one load-on-demand addon per locale (the main addon loads the one for the
// active language with C_AddOns.LoadAddOn):
//   addon/WoWChatHelper_Glossary_<locale>/WoWChatHelper_Glossary_<locale>.toc
//   addon/WoWChatHelper_Glossary_<locale>/Glossary.lua
//     WCH_Glossary = { locale = "<loc>",
//       terms = { { term=, expansion=, tr=, cat=, ambiguity= }, ... },        -- JSON order
//       phrases = { ["<key>"] = { tr=, terms = { { term=, expansion=, tr= } } }, ... } }  -- sorted
//
// The output is deterministic, so tests/glossary_test.js can rebuild it in memory and
// compare it with the committed files. Zero dependencies; Node >= 22.
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const LOCALES = ['zhTW', 'zhCN', 'koKR', 'deDE', 'frFR', 'esES', 'ptBR', 'ruRU', 'itIT'];
const PREFIX = 'WoWChatHelper_Glossary_';
const INTERFACE = '16001';

function loadData(root = ROOT) {
  const dir = path.join(root, 'data', 'glossary');
  const terms = JSON.parse(fs.readFileSync(path.join(dir, 'terms.json'), 'utf8'));
  const phrases = JSON.parse(fs.readFileSync(path.join(dir, 'phrases.json'), 'utf8'));
  let version = '0.0.0';
  try { version = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')).version || version; } catch {}
  return { terms, phrases, version };
}

// A Lua 5.1 double-quoted string literal. UTF-8 passes through as raw bytes; only the
// characters Lua cares about are escaped (no \u{} or \z: those are 5.2+).
function luaStr(s) {
  return '"' + String(s)
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t')
    .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, (c) => '\\' + c.charCodeAt(0)) + '"';
}

function trOf(entry, locale) {
  const v = entry && entry.tr && entry.tr[locale];
  if (typeof v !== 'string' || !v) throw new Error(`missing tr.${locale} for ${JSON.stringify(entry.term || entry.key)}`);
  return v;
}

function buildLua(locale, data) {
  const { terms, phrases } = data;
  const byTerm = new Map(terms.map((t) => [t.term.toLowerCase(), t]));
  const out = [];
  out.push(`-- GENERATED by tools/build-glossary.js from data/glossary/terms.json and phrases.json.`);
  out.push(`-- Do not edit: change the JSON and run \`node tools/build-glossary.js\`.`);
  out.push(`-- WoW Chat Helper offline glossary, language ${locale}.` +
    (locale === 'zhTW' ? '' : ' Translations are AI-generated, not native-reviewed.'));
  out.push(`WCH_Glossary = {`);
  out.push(`  locale = ${luaStr(locale)},`);
  out.push(`  terms = {`);
  for (const t of terms) {
    out.push(`    { term=${luaStr(t.term)}, expansion=${luaStr(t.expansion)}, tr=${luaStr(trOf(t, locale))}, ` +
      `cat=${luaStr(t.cat)}, ambiguity=${luaStr(t.ambiguity || '')} },`);
  }
  out.push(`  },`);
  out.push(`  phrases = {`);
  const sorted = [...phrases].sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  for (const p of sorted) {
    const parts = (p.terms || []).map((name) => {
      const t = byTerm.get(String(name).toLowerCase());
      if (!t) throw new Error(`phrase ${JSON.stringify(p.key)} names unknown term ${JSON.stringify(name)}`);
      return `{ term=${luaStr(t.term)}, expansion=${luaStr(t.expansion)}, tr=${luaStr(trOf(t, locale))} }`;
    });
    out.push(`    [${luaStr(p.key)}] = { tr=${luaStr(trOf(p, locale))}, terms = { ${parts.join(', ')}${parts.length ? ' ' : ''}} },`);
  }
  out.push(`  },`);
  out.push(`}`);
  return out.join('\n') + '\n';
}

function buildToc(locale, data) {
  return [
    `## Interface: ${INTERFACE}`,
    `## Title: WoW Chat Helper Glossary (${locale})`,
    `## Notes: Offline WoW jargon glossary for WoW Chat Helper, language ${locale}. Loaded on demand by WoWChatHelper.`,
    `## Author: tsesc`,
    `## Version: ${data.version}`,
    `## LoadOnDemand: 1`,
    `## Dependencies: WoWChatHelper`,
    ``,
    `Glossary.lua`,
    ``,
  ].join('\n');
}

// { "<path relative to root>": "<content>" } for every generated file.
function outputs(data = loadData()) {
  const files = {};
  for (const loc of LOCALES) {
    const dir = path.join('addon', PREFIX + loc);
    files[path.join(dir, PREFIX + loc + '.toc')] = buildToc(loc, data);
    files[path.join(dir, 'Glossary.lua')] = buildLua(loc, data);
  }
  return files;
}

// Paths (relative) whose committed content differs from a fresh build.
function stale(root = ROOT) {
  const bad = [];
  for (const [rel, content] of Object.entries(outputs(loadData(root)))) {
    let cur = null;
    // Windows checkouts may convert to CRLF; compare content, not line endings.
    try { cur = fs.readFileSync(path.join(root, rel), 'utf8').replace(/\r\n/g, '\n'); } catch {}
    if (cur !== content) bad.push(rel);
  }
  return bad;
}

function main(argv) {
  if (argv.includes('--check')) {
    const bad = stale();
    if (bad.length) {
      console.error('stale glossary files (run `node tools/build-glossary.js`):\n  ' + bad.join('\n  '));
      return 1;
    }
    console.log('glossary addons up to date');
    return 0;
  }
  const data = loadData();
  let n = 0;
  for (const [rel, content] of Object.entries(outputs(data))) {
    const abs = path.join(ROOT, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, content);
    n++;
  }
  console.log(`wrote ${n} files for ${LOCALES.length} locales: ${data.terms.length} terms, ${data.phrases.length} phrases`);
  return 0;
}

module.exports = { LOCALES, PREFIX, INTERFACE, loadData, luaStr, buildLua, buildToc, outputs, stale };

if (require.main === module) process.exitCode = main(process.argv.slice(2));
